#include "string.h"
size_t strlen(const char *স্ট্রিং_ডাটা) { const char *ডাটা_পদ = স্ট্রিং_ডাটা; while (*ডাটা_পদ) ডাটা_পদ++; return ডাটা_পদ - স্ট্রিং_ডাটা; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *X_বোতাম_অক্ষবিন্দু = 첫째값, *Y_বোতাম_অক্ষবিন্দু = 둘째값; while (개수--) { if (*X_বোতাম_অক্ষবিন্দু != *Y_বোতাম_অক্ষবিন্দু) return (int)*X_বোতাম_অক্ষবিন্দু - *Y_বোতাম_অক্ষবিন্দু; X_বোতাম_অক্ষবিন্দু++; Y_বোতাম_অক্ষবিন্দু++; } return 0; }
void *memmove(void *গন্তব্য_ডাটা, const void *স্ট্রিং_ডাটা, size_t 개수) { unsigned char *X_বোতাম_অক্ষবিন্দু = গন্তব্য_ডাটা; const unsigned char *Y_বোতাম_অক্ষবিন্দু = স্ট্রিং_ডাটা; if (X_বোতাম_অক্ষবিন্দু < Y_বোতাম_অক্ষবিন্দু) { for (size_t 순번 = 0; 순번 < 개수; 순번++) X_বোতাম_অক্ষবিন্দু[순번] = Y_বোতাম_অক্ষবিন্দু[순번]; } else { while (개수) { 개수--; X_বোতাম_অক্ষবিন্দু[개수] = Y_বোতাম_অক্ষবিন্দু[개수]; } } return গন্তব্য_ডাটা; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char X_বোতাম_অক্ষবিন্দু = *첫째값++, Y_বোতাম_অক্ষবিন্দু = *둘째값++; if (X_বোতাম_অক্ষবিন্দু != Y_বোতাম_অক্ষবিন্দু) return (int)X_বোতাম_অক্ষবিন্দু-Y_বোতাম_অক্ষবিন্দু; if (!X_বোতাম_অক্ষবিন্দু) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *স্ট্রিং_ডাটা, char **শেষ_করা_অফসেট, int পটভূমি_মান) {
    const char *শুরু_অফসেট = স্ট্রিং_ডাটা; unsigned long মান = 0; int এনকোড_করা_মান = 1, 하나라도 = 0;
    while (*স্ট্রিং_ডাটা == ' ' || (*স্ট্রিং_ডাটা >= 9 && *স্ট্রিং_ডাটা <= 13)) স্ট্রিং_ডাটা++;
    if (*স্ট্রিং_ডাটা == '-' || *স্ট্রিং_ডাটা == '+') { if (*স্ট্রিং_ডাটা == '-') এনকোড_করা_মান = -1; স্ট্রিং_ডাটা++; }
    if (পটভূমি_মান == 0) পটভূমি_মান = 10;
    while (*স্ট্রিং_ডাটা >= '0' && *স্ট্রিং_ডাটা <= '9' && *স্ট্রিং_ডাটা - '0' < পটভূমি_মান) {
        unsigned সংখ্যা_মান = *স্ট্রিং_ডাটা++ - '0'; 하나라도 = 1;
        if (মান > (0x7ffffffffffffffful - সংখ্যা_মান) / (unsigned)পটভূমি_মান) মান = 0x7ffffffffffffffful;
        else মান = মান * পটভূমি_মান + সংখ্যা_মান;
    }
    if (শেষ_করা_অফসেট) *শেষ_করা_অফসেট = (char *)(하나라도 ? স্ট্রিং_ডাটা : শুরু_অফসেট); return এনকোড_করা_মান > 0 ? (long)মান : -(long)মান;
}
int atoi(const char *স্ট্রিং_ডাটা) { return (int)strtol(স্ট্রিং_ডাটা, 0, 10); }
